<?php require '../config/database.php';auth();if(($_SESSION['role']??'')!=='admin')die('ليس لديك صلاحية');$id=(int)$_GET['id'];$s=$pdo->prepare('SELECT * FROM users WHERE id=?');$s->execute([$id]);$r=$s->fetch();if(!$r)die('غير موجود');if($_SERVER['REQUEST_METHOD']==='POST'){$fields='full_name=?,role=?,status=?';$args=[$_POST['full_name'],$_POST['role'],$_POST['status']];if($_POST['password']!==''){$fields.=',password=?';$args[]=password_hash($_POST['password'],PASSWORD_DEFAULT);}$args[]=$id;$s=$pdo->prepare("UPDATE users SET $fields WHERE id=?");$s->execute($args);header('Location:index.php');exit;}?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>تعديل مستخدم</h1><form method="post"><label>الاسم</label><input name="full_name" value="<?=htmlspecialchars($r['full_name'])?>"><label>كلمة مرور جديدة</label><input type="password" name="password"><label>الدور</label><select name="role"><option value="employee" <?=$r['role']==='employee'?'selected':''?>>موظف</option><option value="admin" <?=$r['role']==='admin'?'selected':''?>>مدير</option></select><label>الحالة</label><select name="status"><option value="active">نشط</option><option value="inactive" <?=$r['status']==='inactive'?'selected':''?>>غير نشط</option></select><button>حفظ</button></form></main>
